INSERT INTO `Question` VALUES
('cmqg55u570000sb8va57xe6ny','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-0\",\"tempId\":\"temp-1781584071096-0\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan unsur intrinsik teks dongeng (kiri) dengan definisinya (kanan) secara tepat.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tema\",\"response\":\"gagasan utama yang mendasari jalan cerita\",\"id\":\"ai-1781584071096-0-p0\"},{\"premise\":\"Alur\",\"response\":\"rangkaian peristiwa dari awal hingga akhir\",\"id\":\"ai-1781584071096-0-p1\"},{\"premise\":\"Tokoh\",\"response\":\"pelaku dalam cerita yang menjalankan peristiwa\",\"id\":\"ai-1781584071096-0-p2\"},{\"premise\":\"Latar\",\"response\":\"tempat, waktu, dan suasana terjadinya peristiwa\",\"id\":\"ai-1781584071096-0-p3\"},{\"premise\":\"Amanat\",\"response\":\"pesan moral atau pelajaran yang ingin disampaikan\",\"id\":\"ai-1781584071096-0-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u570001sb8vcqjlge85','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-1\",\"tempId\":\"temp-1781584071096-1\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam teks dongeng, tokoh yang digambarkan memiliki sifat dominan dan menjadi penggerak utama peristiwa disebut ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"tokoh figuran\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-0\"},{\"label\":\"B\",\"text\":\"tokoh utama\",\"isCorrect\":true,\"id\":\"ai-1781584071096-1-opt-1\"},{\"label\":\"C\",\"text\":\"tokoh antagonis saja\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-2\"},{\"label\":\"D\",\"text\":\"latar suasana\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-3\"},{\"label\":\"E\",\"text\":\"konflik eksternal\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u570002sb8vxw8wj0sv','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-2\",\"tempId\":\"temp-1781584071096-2\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pernyataan berikut yang termasuk ciri kebahasaan teks dongeng adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menggunakan kalimat deskriptif untuk menggambarkan tokoh atau tempat\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-0\"},{\"label\":\"B\",\"text\":\"memakai dialog untuk menyampaikan jalan cerita secara dramatik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-1\"},{\"label\":\"C\",\"text\":\"mengandung data angka statistik sebagai bukti peristiwa\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-2\"},{\"label\":\"D\",\"text\":\"banyak menggunakan kata kerja tindakan (misalnya melangkah, berkata, berlari) untuk menggerakkan alur\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-3\"},{\"label\":\"E\",\"text\":\"mengutamakan fakta dan rujukan sumber seperti pada teks laporan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u570003sb8v35054bnb','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-3\",\"tempId\":\"temp-1781584071096-3\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis konflik (kiri) dengan contoh konflik dalam teks dongeng (kanan) yang sesuai.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Konflik batin\",\"response\":\"tokoh ragu antara menuruti hati dan takut pada akibat\",\"id\":\"ai-1781584071096-3-p0\"},{\"premise\":\"Konflik sosial\",\"response\":\"perbedaan kepentingan antarwarga membuat perselisihan\",\"id\":\"ai-1781584071096-3-p1\"},{\"premise\":\"Konflik alam\",\"response\":\"tokoh berhadapan dengan bencana atau kekuatan alam yang mengancam\",\"id\":\"ai-1781584071096-3-p2\"},{\"premise\":\"Konflik dengan tokoh lain\",\"response\":\"tokoh baik melawan tokoh jahat yang ingin mengambil sesuatu\",\"id\":\"ai-1781584071096-3-p3\"},{\"premise\":\"Konflik dengan diri sendiri (kelemahan karakter)\",\"response\":\"tokoh mengulang kesalahan karena sifat malas atau serakah\",\"id\":\"ai-1781584071096-3-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u570004sb8ve55wchti','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-4\",\"tempId\":\"temp-1781584071096-4\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat berikut yang paling tepat untuk menyatakan bagian struktur \'orientasi\' dalam teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Akhirnya, kutukan itu lenyap setelah ia menolong tanpa pamrih.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-0\"},{\"label\":\"B\",\"text\":\"Sejak pagi hari, desa itu bersiap menyambut bulan purnama yang ditunggu-tunggu.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-4-opt-1\"},{\"label\":\"C\",\"text\":\"Namun, rencana si serigala licik gagal total ketika mangsanya berpura-pura tidak takut.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-2\"},{\"label\":\"D\",\"text\":\"Begitulah ia memahami bahwa kebohongan selalu berujung pada penyesalan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-3\"},{\"label\":\"E\",\"text\":\"Pada malam itu, semua warga berduka karena kemarau panjang menghampiri ladang mereka.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u570005sb8vtmmp7851','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-5\",\"tempId\":\"temp-1781584071096-5\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Bacalah kalimat-kalimat dongeng berikut. Kalimat mana yang menunjukkan peristiwa sebab-akibat (kausalitas) secara jelas? (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Karena ia sering ingkar janji, raja akhirnya menjauhkan dirinya dari istana.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-0\"},{\"label\":\"B\",\"text\":\"Pada saat fajar menyingsing, burung-burung beterbangan di atas sungai.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-1\"},{\"label\":\"C\",\"text\":\"Akibat sifat serakah, harta yang ia kumpulkan berubah menjadi debu di genggamannya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-2\"},{\"label\":\"D\",\"text\":\"Ia berlari cepat, lalu tertawa bersama teman-temannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-3\"},{\"label\":\"E\",\"text\":\"Maka dari itu, ia belajar meminta maaf sebelum terlambat menyesal.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u580006sb8vaihumina','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-6\",\"tempId\":\"temp-1781584071096-6\",\"type\":\"pilihan_ganda\",\"text\":\"Manakah pernyataan yang paling tepat tentang \'amanat\' dalam teks dongeng?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Amanat selalu dinyatakan secara eksplisit dalam satu kalimat langsung di akhir cerita.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat adalah tujuan penulis agar pembaca memahami karakter tokoh tanpa memberi pesan moral.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-1\"},{\"label\":\"C\",\"text\":\"Amanat merupakan pesan moral/pelajaran yang dapat ditarik dari peristiwa dan konflik dalam cerita.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-6-opt-2\"},{\"label\":\"D\",\"text\":\"Amanat hanya berupa deskripsi latar tempat yang membuat cerita lebih menarik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-3\"},{\"label\":\"E\",\"text\":\"Amanat identik dengan tema sehingga tidak perlu dianalisis secara terpisah.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u580007sb8vyohjx8xn','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-7\",\"tempId\":\"temp-1781584071096-7\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis alur (kiri) dengan ciri peristiwanya (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Alur maju\",\"response\":\"peristiwa berjalan dari awal, tengah, menuju akhir secara kronologis\",\"id\":\"ai-1781584071096-7-p0\"},{\"premise\":\"Alur mundur\",\"response\":\"cerita diawali pada bagian akhir, lalu kembali menjelaskan peristiwa sebelumnya\",\"id\":\"ai-1781584071096-7-p1\"},{\"premise\":\"Alur campuran\",\"response\":\"menggabungkan alur maju dan mundur untuk membangun penjelasan konflik\",\"id\":\"ai-1781584071096-7-p2\"},{\"premise\":\"Alur dengan puncak konflik\",\"response\":\"mencapai titik paling menentukan yang membuat nasib tokoh berubah\",\"id\":\"ai-1781584071096-7-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u580008sb8vpoiyn5hp','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-8\",\"tempId\":\"temp-1781584071096-8\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pada teks dongeng, pilihan kata berikut yang biasanya mendukung nuansa cerita (naratif/khayal) adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"pada suatu hari\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-0\"},{\"label\":\"B\",\"text\":\"termasuk dalam laporan penelitian\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-1\"},{\"label\":\"C\",\"text\":\"tatkala angin berbisik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-2\"},{\"label\":\"D\",\"text\":\"berdasarkan data statistik tahun 2023\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-3\"},{\"label\":\"E\",\"text\":\"seketika itu juga\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u580009sb8v4rs58iw3','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-9\",\"tempId\":\"temp-1781584071096-9\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat yang paling tepat untuk menyusun bagian \'penutup/hasil\' teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Setelah peristiwa itu, tokoh utama menyusun rencana baru untuk menantang bahaya berikutnya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-0\"},{\"label\":\"B\",\"text\":\"Ketika semuanya hening, si tokoh jahat menyadari kekeliruannya dan meminta maaf.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-9-opt-1\"},{\"label\":\"C\",\"text\":\"Di tengah jalan, angin semakin kencang dan ia terus berlari tanpa tujuan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-2\"},{\"label\":\"D\",\"text\":\"Pada suatu hari, hiduplah seorang anak yang rajin membantu orang tua.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-3\"},{\"label\":\"E\",\"text\":\"Karena ia sombong, banyak orang tidak mau bekerja sama dengannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u58000asb8vez7x8f90','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-10\",\"tempId\":\"temp-1781584071096-10\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan jenis tokoh (kiri) dengan perannya dalam konflik dongeng (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tokoh protagonis\",\"response\":\"membawa nilai baik dan umumnya menghadapi rintangan untuk mencapai tujuan\",\"id\":\"ai-1781584071096-10-p0\"},{\"premise\":\"Tokoh antagonis\",\"response\":\"menjadi penghambat yang menimbulkan konflik atau kerugian bagi tokoh lain\",\"id\":\"ai-1781584071096-10-p1\"},{\"premise\":\"Tokoh penolong\",\"response\":\"memberi bantuan, petunjuk, atau perlindungan dalam situasi sulit\",\"id\":\"ai-1781584071096-10-p2\"},{\"premise\":\"Tokoh yang menjadi korban\",\"response\":\"pihak yang dirugikan akibat tindakan tokoh antagonis atau keadaan\",\"id\":\"ai-1781584071096-10-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u58000bsb8vzy9y2w12','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-11\",\"tempId\":\"temp-1781584071096-11\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam analisis teks dongeng, manakah kegiatan yang paling tepat untuk menentukan \'tema\'?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menghafalkan nama tokoh satu per satu agar cerita mudah diingat\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-0\"},{\"label\":\"B\",\"text\":\"mencari gagasan utama yang berulang lewat peristiwa dan konflik dalam cerita\",\"isCorrect\":true,\"id\":\"ai-1781584071096-11-opt-1\"},{\"label\":\"C\",\"text\":\"menentukan apakah latar terjadi di desa atau kota sebagai tema utama\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-2\"},{\"label\":\"D\",\"text\":\"mengukur panjang kalimat agar sesuai kaidah penulisan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-3\"},{\"label\":\"E\",\"text\":\"menentukan jenis huruf yang digunakan dalam teks\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u58000csb8vtd7oqyq2','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-12\",\"tempId\":\"temp-1781584071096-12\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Identifikasi bagian yang menunjukkan \'kemunculan konflik\' dalam dongeng. Pilih semua pernyataan yang benar. (diasumsikan konflik mulai saat masalah pokok pertama kali dipersengketakan).\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Tokoh utama mengetahui bahwa janji yang ia buat tidak dapat ditepati karena sesuatu yang di luar kendalinya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-0\"},{\"label\":\"B\",\"text\":\"Tokoh jahat menyembunyikan benda penting sehingga tokoh utama kehilangan jalan untuk menyelesaikan masalah.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-1\"},{\"label\":\"C\",\"text\":\"Tokoh utama berkelana mencari petunjuk setelah mendapatkan informasi awal tentang keberadaan benda itu.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-2\"},{\"label\":\"D\",\"text\":\"Tindakan tokoh antagonis menimbulkan pertentangan terbuka yang memicu serangkaian peristiwa berikutnya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-3\"},{\"label\":\"E\",\"text\":\"Kemudian tokoh utama menemukan solusi dan konflik selesai dengan kemenangan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u58000dsb8vcg44dy3m','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-13\",\"tempId\":\"temp-1781584071096-13\",\"type\":\"pilihan_ganda\",\"text\":\"Perhatikan dua kalimat berikut yang berasal dari dongeng: (1) \'Akhirnya ia mengaku dan meminta maaf.\' (2) \'Ia mengaku dan meminta maaf, lalu semua warga menerimanya kembali.\' Kalimat mana yang lebih tepat untuk menggambarkan hubungan urutan peristiwa dalam alur?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Kalimat (1) karena ada kata \'akhirnya\'.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-0\"},{\"label\":\"B\",\"text\":\"Kalimat (2) karena menampilkan urutan dengan \'lalu\'.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-13-opt-1\"},{\"label\":\"C\",\"text\":\"Keduanya sama karena keduanya hanya berisi pengakuan tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-2\"},{\"label\":\"D\",\"text\":\"Kalimat (1) karena \'akhirnya\' adalah penanda konflik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-3\"},{\"label\":\"E\",\"text\":\"Kalimat (2) salah karena menggunakan \'lalu\' sehingga tidak termasuk teks dongeng.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55u58000esb8vw3wvbyba','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-14\",\"tempId\":\"temp-1781584071096-14\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pilih pernyataan yang tepat tentang hubungan tema, konflik, dan amanat dalam teks dongeng. (pilih semua yang benar)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Konflik menjadi sarana untuk menguji nilai-nilai yang terkait dengan tema.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat selalu identik dengan solusi konflik tanpa mempertimbangkan peristiwa lain.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-1\"},{\"label\":\"C\",\"text\":\"Tema dapat ditarik dari pola peristiwa, sedangkan amanat merupakan pelajaran moral yang dapat disimpulkan dari hasil akhir.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-2\"},{\"label\":\"D\",\"text\":\"Konflik tidak diperlukan dalam dongeng karena dongeng hanya berisi deskripsi tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-3\"},{\"label\":\"E\",\"text\":\"Jika tokoh protagonis menerima konsekuensi karena tindakan tertentu, amanat umumnya dapat ditafsirkan melalui konsekuensi tersebut.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.090','2026-06-16 04:28:00.090'),
('cmqg55ury000fsb8vldbk2ta6','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-0\",\"tempId\":\"temp-1781584071096-0\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan unsur intrinsik teks dongeng (kiri) dengan definisinya (kanan) secara tepat.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tema\",\"response\":\"gagasan utama yang mendasari jalan cerita\",\"id\":\"ai-1781584071096-0-p0\"},{\"premise\":\"Alur\",\"response\":\"rangkaian peristiwa dari awal hingga akhir\",\"id\":\"ai-1781584071096-0-p1\"},{\"premise\":\"Tokoh\",\"response\":\"pelaku dalam cerita yang menjalankan peristiwa\",\"id\":\"ai-1781584071096-0-p2\"},{\"premise\":\"Latar\",\"response\":\"tempat, waktu, dan suasana terjadinya peristiwa\",\"id\":\"ai-1781584071096-0-p3\"},{\"premise\":\"Amanat\",\"response\":\"pesan moral atau pelajaran yang ingin disampaikan\",\"id\":\"ai-1781584071096-0-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000gsb8vfyugp59h','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-1\",\"tempId\":\"temp-1781584071096-1\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam teks dongeng, tokoh yang digambarkan memiliki sifat dominan dan menjadi penggerak utama peristiwa disebut ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"tokoh figuran\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-0\"},{\"label\":\"B\",\"text\":\"tokoh utama\",\"isCorrect\":true,\"id\":\"ai-1781584071096-1-opt-1\"},{\"label\":\"C\",\"text\":\"tokoh antagonis saja\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-2\"},{\"label\":\"D\",\"text\":\"latar suasana\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-3\"},{\"label\":\"E\",\"text\":\"konflik eksternal\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000hsb8vpg3ut918','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-2\",\"tempId\":\"temp-1781584071096-2\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pernyataan berikut yang termasuk ciri kebahasaan teks dongeng adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menggunakan kalimat deskriptif untuk menggambarkan tokoh atau tempat\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-0\"},{\"label\":\"B\",\"text\":\"memakai dialog untuk menyampaikan jalan cerita secara dramatik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-1\"},{\"label\":\"C\",\"text\":\"mengandung data angka statistik sebagai bukti peristiwa\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-2\"},{\"label\":\"D\",\"text\":\"banyak menggunakan kata kerja tindakan (misalnya melangkah, berkata, berlari) untuk menggerakkan alur\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-3\"},{\"label\":\"E\",\"text\":\"mengutamakan fakta dan rujukan sumber seperti pada teks laporan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000isb8vsz04u6v9','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-3\",\"tempId\":\"temp-1781584071096-3\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis konflik (kiri) dengan contoh konflik dalam teks dongeng (kanan) yang sesuai.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Konflik batin\",\"response\":\"tokoh ragu antara menuruti hati dan takut pada akibat\",\"id\":\"ai-1781584071096-3-p0\"},{\"premise\":\"Konflik sosial\",\"response\":\"perbedaan kepentingan antarwarga membuat perselisihan\",\"id\":\"ai-1781584071096-3-p1\"},{\"premise\":\"Konflik alam\",\"response\":\"tokoh berhadapan dengan bencana atau kekuatan alam yang mengancam\",\"id\":\"ai-1781584071096-3-p2\"},{\"premise\":\"Konflik dengan tokoh lain\",\"response\":\"tokoh baik melawan tokoh jahat yang ingin mengambil sesuatu\",\"id\":\"ai-1781584071096-3-p3\"},{\"premise\":\"Konflik dengan diri sendiri (kelemahan karakter)\",\"response\":\"tokoh mengulang kesalahan karena sifat malas atau serakah\",\"id\":\"ai-1781584071096-3-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000jsb8vezku5cpb','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-4\",\"tempId\":\"temp-1781584071096-4\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat berikut yang paling tepat untuk menyatakan bagian struktur \'orientasi\' dalam teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Akhirnya, kutukan itu lenyap setelah ia menolong tanpa pamrih.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-0\"},{\"label\":\"B\",\"text\":\"Sejak pagi hari, desa itu bersiap menyambut bulan purnama yang ditunggu-tunggu.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-4-opt-1\"},{\"label\":\"C\",\"text\":\"Namun, rencana si serigala licik gagal total ketika mangsanya berpura-pura tidak takut.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-2\"},{\"label\":\"D\",\"text\":\"Begitulah ia memahami bahwa kebohongan selalu berujung pada penyesalan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-3\"},{\"label\":\"E\",\"text\":\"Pada malam itu, semua warga berduka karena kemarau panjang menghampiri ladang mereka.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000ksb8v7j3dajbb','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-5\",\"tempId\":\"temp-1781584071096-5\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Bacalah kalimat-kalimat dongeng berikut. Kalimat mana yang menunjukkan peristiwa sebab-akibat (kausalitas) secara jelas? (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Karena ia sering ingkar janji, raja akhirnya menjauhkan dirinya dari istana.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-0\"},{\"label\":\"B\",\"text\":\"Pada saat fajar menyingsing, burung-burung beterbangan di atas sungai.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-1\"},{\"label\":\"C\",\"text\":\"Akibat sifat serakah, harta yang ia kumpulkan berubah menjadi debu di genggamannya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-2\"},{\"label\":\"D\",\"text\":\"Ia berlari cepat, lalu tertawa bersama teman-temannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-3\"},{\"label\":\"E\",\"text\":\"Maka dari itu, ia belajar meminta maaf sebelum terlambat menyesal.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000lsb8v68b8mlw6','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-6\",\"tempId\":\"temp-1781584071096-6\",\"type\":\"pilihan_ganda\",\"text\":\"Manakah pernyataan yang paling tepat tentang \'amanat\' dalam teks dongeng?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Amanat selalu dinyatakan secara eksplisit dalam satu kalimat langsung di akhir cerita.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat adalah tujuan penulis agar pembaca memahami karakter tokoh tanpa memberi pesan moral.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-1\"},{\"label\":\"C\",\"text\":\"Amanat merupakan pesan moral/pelajaran yang dapat ditarik dari peristiwa dan konflik dalam cerita.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-6-opt-2\"},{\"label\":\"D\",\"text\":\"Amanat hanya berupa deskripsi latar tempat yang membuat cerita lebih menarik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-3\"},{\"label\":\"E\",\"text\":\"Amanat identik dengan tema sehingga tidak perlu dianalisis secara terpisah.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000msb8vzuetjm43','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-7\",\"tempId\":\"temp-1781584071096-7\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis alur (kiri) dengan ciri peristiwanya (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Alur maju\",\"response\":\"peristiwa berjalan dari awal, tengah, menuju akhir secara kronologis\",\"id\":\"ai-1781584071096-7-p0\"},{\"premise\":\"Alur mundur\",\"response\":\"cerita diawali pada bagian akhir, lalu kembali menjelaskan peristiwa sebelumnya\",\"id\":\"ai-1781584071096-7-p1\"},{\"premise\":\"Alur campuran\",\"response\":\"menggabungkan alur maju dan mundur untuk membangun penjelasan konflik\",\"id\":\"ai-1781584071096-7-p2\"},{\"premise\":\"Alur dengan puncak konflik\",\"response\":\"mencapai titik paling menentukan yang membuat nasib tokoh berubah\",\"id\":\"ai-1781584071096-7-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000nsb8verwrf4xt','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-8\",\"tempId\":\"temp-1781584071096-8\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pada teks dongeng, pilihan kata berikut yang biasanya mendukung nuansa cerita (naratif/khayal) adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"pada suatu hari\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-0\"},{\"label\":\"B\",\"text\":\"termasuk dalam laporan penelitian\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-1\"},{\"label\":\"C\",\"text\":\"tatkala angin berbisik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-2\"},{\"label\":\"D\",\"text\":\"berdasarkan data statistik tahun 2023\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-3\"},{\"label\":\"E\",\"text\":\"seketika itu juga\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000osb8vohnj4xt5','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-9\",\"tempId\":\"temp-1781584071096-9\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat yang paling tepat untuk menyusun bagian \'penutup/hasil\' teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Setelah peristiwa itu, tokoh utama menyusun rencana baru untuk menantang bahaya berikutnya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-0\"},{\"label\":\"B\",\"text\":\"Ketika semuanya hening, si tokoh jahat menyadari kekeliruannya dan meminta maaf.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-9-opt-1\"},{\"label\":\"C\",\"text\":\"Di tengah jalan, angin semakin kencang dan ia terus berlari tanpa tujuan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-2\"},{\"label\":\"D\",\"text\":\"Pada suatu hari, hiduplah seorang anak yang rajin membantu orang tua.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-3\"},{\"label\":\"E\",\"text\":\"Karena ia sombong, banyak orang tidak mau bekerja sama dengannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000psb8vpp878j1l','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-10\",\"tempId\":\"temp-1781584071096-10\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan jenis tokoh (kiri) dengan perannya dalam konflik dongeng (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tokoh protagonis\",\"response\":\"membawa nilai baik dan umumnya menghadapi rintangan untuk mencapai tujuan\",\"id\":\"ai-1781584071096-10-p0\"},{\"premise\":\"Tokoh antagonis\",\"response\":\"menjadi penghambat yang menimbulkan konflik atau kerugian bagi tokoh lain\",\"id\":\"ai-1781584071096-10-p1\"},{\"premise\":\"Tokoh penolong\",\"response\":\"memberi bantuan, petunjuk, atau perlindungan dalam situasi sulit\",\"id\":\"ai-1781584071096-10-p2\"},{\"premise\":\"Tokoh yang menjadi korban\",\"response\":\"pihak yang dirugikan akibat tindakan tokoh antagonis atau keadaan\",\"id\":\"ai-1781584071096-10-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000qsb8vbudyf4of','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-11\",\"tempId\":\"temp-1781584071096-11\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam analisis teks dongeng, manakah kegiatan yang paling tepat untuk menentukan \'tema\'?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menghafalkan nama tokoh satu per satu agar cerita mudah diingat\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-0\"},{\"label\":\"B\",\"text\":\"mencari gagasan utama yang berulang lewat peristiwa dan konflik dalam cerita\",\"isCorrect\":true,\"id\":\"ai-1781584071096-11-opt-1\"},{\"label\":\"C\",\"text\":\"menentukan apakah latar terjadi di desa atau kota sebagai tema utama\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-2\"},{\"label\":\"D\",\"text\":\"mengukur panjang kalimat agar sesuai kaidah penulisan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-3\"},{\"label\":\"E\",\"text\":\"menentukan jenis huruf yang digunakan dalam teks\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000rsb8vr2bkih5a','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-12\",\"tempId\":\"temp-1781584071096-12\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Identifikasi bagian yang menunjukkan \'kemunculan konflik\' dalam dongeng. Pilih semua pernyataan yang benar. (diasumsikan konflik mulai saat masalah pokok pertama kali dipersengketakan).\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Tokoh utama mengetahui bahwa janji yang ia buat tidak dapat ditepati karena sesuatu yang di luar kendalinya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-0\"},{\"label\":\"B\",\"text\":\"Tokoh jahat menyembunyikan benda penting sehingga tokoh utama kehilangan jalan untuk menyelesaikan masalah.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-1\"},{\"label\":\"C\",\"text\":\"Tokoh utama berkelana mencari petunjuk setelah mendapatkan informasi awal tentang keberadaan benda itu.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-2\"},{\"label\":\"D\",\"text\":\"Tindakan tokoh antagonis menimbulkan pertentangan terbuka yang memicu serangkaian peristiwa berikutnya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-3\"},{\"label\":\"E\",\"text\":\"Kemudian tokoh utama menemukan solusi dan konflik selesai dengan kemenangan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000ssb8vecaiirq9','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-13\",\"tempId\":\"temp-1781584071096-13\",\"type\":\"pilihan_ganda\",\"text\":\"Perhatikan dua kalimat berikut yang berasal dari dongeng: (1) \'Akhirnya ia mengaku dan meminta maaf.\' (2) \'Ia mengaku dan meminta maaf, lalu semua warga menerimanya kembali.\' Kalimat mana yang lebih tepat untuk menggambarkan hubungan urutan peristiwa dalam alur?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Kalimat (1) karena ada kata \'akhirnya\'.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-0\"},{\"label\":\"B\",\"text\":\"Kalimat (2) karena menampilkan urutan dengan \'lalu\'.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-13-opt-1\"},{\"label\":\"C\",\"text\":\"Keduanya sama karena keduanya hanya berisi pengakuan tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-2\"},{\"label\":\"D\",\"text\":\"Kalimat (1) karena \'akhirnya\' adalah penanda konflik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-3\"},{\"label\":\"E\",\"text\":\"Kalimat (2) salah karena menggunakan \'lalu\' sehingga tidak termasuk teks dongeng.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
('cmqg55ury000tsb8v3xb82cdg','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-14\",\"tempId\":\"temp-1781584071096-14\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pilih pernyataan yang tepat tentang hubungan tema, konflik, dan amanat dalam teks dongeng. (pilih semua yang benar)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Konflik menjadi sarana untuk menguji nilai-nilai yang terkait dengan tema.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat selalu identik dengan solusi konflik tanpa mempertimbangkan peristiwa lain.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-1\"},{\"label\":\"C\",\"text\":\"Tema dapat ditarik dari pola peristiwa, sedangkan amanat merupakan pelajaran moral yang dapat disimpulkan dari hasil akhir.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-2\"},{\"label\":\"D\",\"text\":\"Konflik tidak diperlukan dalam dongeng karena dongeng hanya berisi deskripsi tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-3\"},{\"label\":\"E\",\"text\":\"Jika tokoh protagonis menerima konsekuensi karena tindakan tertentu, amanat umumnya dapat ditafsirkan melalui konsekuensi tersebut.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:00.910','2026-06-16 04:28:00.910'),
