('cmqg55wim006asb8v32gm1yy8','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-1\",\"tempId\":\"temp-1781584071096-1\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam teks dongeng, tokoh yang digambarkan memiliki sifat dominan dan menjadi penggerak utama peristiwa disebut ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"tokoh figuran\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-0\"},{\"label\":\"B\",\"text\":\"tokoh utama\",\"isCorrect\":true,\"id\":\"ai-1781584071096-1-opt-1\"},{\"label\":\"C\",\"text\":\"tokoh antagonis saja\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-2\"},{\"label\":\"D\",\"text\":\"latar suasana\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-3\"},{\"label\":\"E\",\"text\":\"konflik eksternal\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55wim006bsb8vnplld5yz','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-2\",\"tempId\":\"temp-1781584071096-2\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pernyataan berikut yang termasuk ciri kebahasaan teks dongeng adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menggunakan kalimat deskriptif untuk menggambarkan tokoh atau tempat\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-0\"},{\"label\":\"B\",\"text\":\"memakai dialog untuk menyampaikan jalan cerita secara dramatik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-1\"},{\"label\":\"C\",\"text\":\"mengandung data angka statistik sebagai bukti peristiwa\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-2\"},{\"label\":\"D\",\"text\":\"banyak menggunakan kata kerja tindakan (misalnya melangkah, berkata, berlari) untuk menggerakkan alur\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-3\"},{\"label\":\"E\",\"text\":\"mengutamakan fakta dan rujukan sumber seperti pada teks laporan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55wim006csb8v7qtkm7nq','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-3\",\"tempId\":\"temp-1781584071096-3\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis konflik (kiri) dengan contoh konflik dalam teks dongeng (kanan) yang sesuai.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Konflik batin\",\"response\":\"tokoh ragu antara menuruti hati dan takut pada akibat\",\"id\":\"ai-1781584071096-3-p0\"},{\"premise\":\"Konflik sosial\",\"response\":\"perbedaan kepentingan antarwarga membuat perselisihan\",\"id\":\"ai-1781584071096-3-p1\"},{\"premise\":\"Konflik alam\",\"response\":\"tokoh berhadapan dengan bencana atau kekuatan alam yang mengancam\",\"id\":\"ai-1781584071096-3-p2\"},{\"premise\":\"Konflik dengan tokoh lain\",\"response\":\"tokoh baik melawan tokoh jahat yang ingin mengambil sesuatu\",\"id\":\"ai-1781584071096-3-p3\"},{\"premise\":\"Konflik dengan diri sendiri (kelemahan karakter)\",\"response\":\"tokoh mengulang kesalahan karena sifat malas atau serakah\",\"id\":\"ai-1781584071096-3-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006dsb8vxny44fnb','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-4\",\"tempId\":\"temp-1781584071096-4\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat berikut yang paling tepat untuk menyatakan bagian struktur \'orientasi\' dalam teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Akhirnya, kutukan itu lenyap setelah ia menolong tanpa pamrih.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-0\"},{\"label\":\"B\",\"text\":\"Sejak pagi hari, desa itu bersiap menyambut bulan purnama yang ditunggu-tunggu.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-4-opt-1\"},{\"label\":\"C\",\"text\":\"Namun, rencana si serigala licik gagal total ketika mangsanya berpura-pura tidak takut.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-2\"},{\"label\":\"D\",\"text\":\"Begitulah ia memahami bahwa kebohongan selalu berujung pada penyesalan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-3\"},{\"label\":\"E\",\"text\":\"Pada malam itu, semua warga berduka karena kemarau panjang menghampiri ladang mereka.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006esb8vobpubm39','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-5\",\"tempId\":\"temp-1781584071096-5\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Bacalah kalimat-kalimat dongeng berikut. Kalimat mana yang menunjukkan peristiwa sebab-akibat (kausalitas) secara jelas? (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Karena ia sering ingkar janji, raja akhirnya menjauhkan dirinya dari istana.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-0\"},{\"label\":\"B\",\"text\":\"Pada saat fajar menyingsing, burung-burung beterbangan di atas sungai.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-1\"},{\"label\":\"C\",\"text\":\"Akibat sifat serakah, harta yang ia kumpulkan berubah menjadi debu di genggamannya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-2\"},{\"label\":\"D\",\"text\":\"Ia berlari cepat, lalu tertawa bersama teman-temannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-3\"},{\"label\":\"E\",\"text\":\"Maka dari itu, ia belajar meminta maaf sebelum terlambat menyesal.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006fsb8vmu6pnvv5','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-6\",\"tempId\":\"temp-1781584071096-6\",\"type\":\"pilihan_ganda\",\"text\":\"Manakah pernyataan yang paling tepat tentang \'amanat\' dalam teks dongeng?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Amanat selalu dinyatakan secara eksplisit dalam satu kalimat langsung di akhir cerita.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat adalah tujuan penulis agar pembaca memahami karakter tokoh tanpa memberi pesan moral.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-1\"},{\"label\":\"C\",\"text\":\"Amanat merupakan pesan moral/pelajaran yang dapat ditarik dari peristiwa dan konflik dalam cerita.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-6-opt-2\"},{\"label\":\"D\",\"text\":\"Amanat hanya berupa deskripsi latar tempat yang membuat cerita lebih menarik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-3\"},{\"label\":\"E\",\"text\":\"Amanat identik dengan tema sehingga tidak perlu dianalisis secara terpisah.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006gsb8vr8m6xw17','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-7\",\"tempId\":\"temp-1781584071096-7\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis alur (kiri) dengan ciri peristiwanya (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Alur maju\",\"response\":\"peristiwa berjalan dari awal, tengah, menuju akhir secara kronologis\",\"id\":\"ai-1781584071096-7-p0\"},{\"premise\":\"Alur mundur\",\"response\":\"cerita diawali pada bagian akhir, lalu kembali menjelaskan peristiwa sebelumnya\",\"id\":\"ai-1781584071096-7-p1\"},{\"premise\":\"Alur campuran\",\"response\":\"menggabungkan alur maju dan mundur untuk membangun penjelasan konflik\",\"id\":\"ai-1781584071096-7-p2\"},{\"premise\":\"Alur dengan puncak konflik\",\"response\":\"mencapai titik paling menentukan yang membuat nasib tokoh berubah\",\"id\":\"ai-1781584071096-7-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006hsb8vb9t9hqzb','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-8\",\"tempId\":\"temp-1781584071096-8\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pada teks dongeng, pilihan kata berikut yang biasanya mendukung nuansa cerita (naratif/khayal) adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"pada suatu hari\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-0\"},{\"label\":\"B\",\"text\":\"termasuk dalam laporan penelitian\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-1\"},{\"label\":\"C\",\"text\":\"tatkala angin berbisik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-2\"},{\"label\":\"D\",\"text\":\"berdasarkan data statistik tahun 2023\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-3\"},{\"label\":\"E\",\"text\":\"seketika itu juga\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006isb8v4o4h1wpr','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-9\",\"tempId\":\"temp-1781584071096-9\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat yang paling tepat untuk menyusun bagian \'penutup/hasil\' teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Setelah peristiwa itu, tokoh utama menyusun rencana baru untuk menantang bahaya berikutnya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-0\"},{\"label\":\"B\",\"text\":\"Ketika semuanya hening, si tokoh jahat menyadari kekeliruannya dan meminta maaf.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-9-opt-1\"},{\"label\":\"C\",\"text\":\"Di tengah jalan, angin semakin kencang dan ia terus berlari tanpa tujuan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-2\"},{\"label\":\"D\",\"text\":\"Pada suatu hari, hiduplah seorang anak yang rajin membantu orang tua.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-3\"},{\"label\":\"E\",\"text\":\"Karena ia sombong, banyak orang tidak mau bekerja sama dengannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006jsb8vqmm8zjxk','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-10\",\"tempId\":\"temp-1781584071096-10\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan jenis tokoh (kiri) dengan perannya dalam konflik dongeng (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tokoh protagonis\",\"response\":\"membawa nilai baik dan umumnya menghadapi rintangan untuk mencapai tujuan\",\"id\":\"ai-1781584071096-10-p0\"},{\"premise\":\"Tokoh antagonis\",\"response\":\"menjadi penghambat yang menimbulkan konflik atau kerugian bagi tokoh lain\",\"id\":\"ai-1781584071096-10-p1\"},{\"premise\":\"Tokoh penolong\",\"response\":\"memberi bantuan, petunjuk, atau perlindungan dalam situasi sulit\",\"id\":\"ai-1781584071096-10-p2\"},{\"premise\":\"Tokoh yang menjadi korban\",\"response\":\"pihak yang dirugikan akibat tindakan tokoh antagonis atau keadaan\",\"id\":\"ai-1781584071096-10-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006ksb8vwbie4dxi','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-11\",\"tempId\":\"temp-1781584071096-11\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam analisis teks dongeng, manakah kegiatan yang paling tepat untuk menentukan \'tema\'?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menghafalkan nama tokoh satu per satu agar cerita mudah diingat\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-0\"},{\"label\":\"B\",\"text\":\"mencari gagasan utama yang berulang lewat peristiwa dan konflik dalam cerita\",\"isCorrect\":true,\"id\":\"ai-1781584071096-11-opt-1\"},{\"label\":\"C\",\"text\":\"menentukan apakah latar terjadi di desa atau kota sebagai tema utama\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-2\"},{\"label\":\"D\",\"text\":\"mengukur panjang kalimat agar sesuai kaidah penulisan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-3\"},{\"label\":\"E\",\"text\":\"menentukan jenis huruf yang digunakan dalam teks\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006lsb8vhqyglg34','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-12\",\"tempId\":\"temp-1781584071096-12\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Identifikasi bagian yang menunjukkan \'kemunculan konflik\' dalam dongeng. Pilih semua pernyataan yang benar. (diasumsikan konflik mulai saat masalah pokok pertama kali dipersengketakan).\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Tokoh utama mengetahui bahwa janji yang ia buat tidak dapat ditepati karena sesuatu yang di luar kendalinya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-0\"},{\"label\":\"B\",\"text\":\"Tokoh jahat menyembunyikan benda penting sehingga tokoh utama kehilangan jalan untuk menyelesaikan masalah.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-1\"},{\"label\":\"C\",\"text\":\"Tokoh utama berkelana mencari petunjuk setelah mendapatkan informasi awal tentang keberadaan benda itu.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-2\"},{\"label\":\"D\",\"text\":\"Tindakan tokoh antagonis menimbulkan pertentangan terbuka yang memicu serangkaian peristiwa berikutnya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-3\"},{\"label\":\"E\",\"text\":\"Kemudian tokoh utama menemukan solusi dan konflik selesai dengan kemenangan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006msb8vd12wter8','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-13\",\"tempId\":\"temp-1781584071096-13\",\"type\":\"pilihan_ganda\",\"text\":\"Perhatikan dua kalimat berikut yang berasal dari dongeng: (1) \'Akhirnya ia mengaku dan meminta maaf.\' (2) \'Ia mengaku dan meminta maaf, lalu semua warga menerimanya kembali.\' Kalimat mana yang lebih tepat untuk menggambarkan hubungan urutan peristiwa dalam alur?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Kalimat (1) karena ada kata \'akhirnya\'.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-0\"},{\"label\":\"B\",\"text\":\"Kalimat (2) karena menampilkan urutan dengan \'lalu\'.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-13-opt-1\"},{\"label\":\"C\",\"text\":\"Keduanya sama karena keduanya hanya berisi pengakuan tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-2\"},{\"label\":\"D\",\"text\":\"Kalimat (1) karena \'akhirnya\' adalah penanda konflik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-3\"},{\"label\":\"E\",\"text\":\"Kalimat (2) salah karena menggunakan \'lalu\' sehingga tidak termasuk teks dongeng.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55win006nsb8v2zzuypsf','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-14\",\"tempId\":\"temp-1781584071096-14\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pilih pernyataan yang tepat tentang hubungan tema, konflik, dan amanat dalam teks dongeng. (pilih semua yang benar)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Konflik menjadi sarana untuk menguji nilai-nilai yang terkait dengan tema.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat selalu identik dengan solusi konflik tanpa mempertimbangkan peristiwa lain.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-1\"},{\"label\":\"C\",\"text\":\"Tema dapat ditarik dari pola peristiwa, sedangkan amanat merupakan pelajaran moral yang dapat disimpulkan dari hasil akhir.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-2\"},{\"label\":\"D\",\"text\":\"Konflik tidak diperlukan dalam dongeng karena dongeng hanya berisi deskripsi tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-3\"},{\"label\":\"E\",\"text\":\"Jika tokoh protagonis menerima konsekuensi karena tindakan tertentu, amanat umumnya dapat ditafsirkan melalui konsekuensi tersebut.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.166','2026-06-16 04:28:03.166'),
('cmqg55wne006osb8vrto7alvw','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-0\",\"tempId\":\"temp-1781584071096-0\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan unsur intrinsik teks dongeng (kiri) dengan definisinya (kanan) secara tepat.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tema\",\"response\":\"gagasan utama yang mendasari jalan cerita\",\"id\":\"ai-1781584071096-0-p0\"},{\"premise\":\"Alur\",\"response\":\"rangkaian peristiwa dari awal hingga akhir\",\"id\":\"ai-1781584071096-0-p1\"},{\"premise\":\"Tokoh\",\"response\":\"pelaku dalam cerita yang menjalankan peristiwa\",\"id\":\"ai-1781584071096-0-p2\"},{\"premise\":\"Latar\",\"response\":\"tempat, waktu, dan suasana terjadinya peristiwa\",\"id\":\"ai-1781584071096-0-p3\"},{\"premise\":\"Amanat\",\"response\":\"pesan moral atau pelajaran yang ingin disampaikan\",\"id\":\"ai-1781584071096-0-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006psb8vc5pj8uas','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-1\",\"tempId\":\"temp-1781584071096-1\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam teks dongeng, tokoh yang digambarkan memiliki sifat dominan dan menjadi penggerak utama peristiwa disebut ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"tokoh figuran\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-0\"},{\"label\":\"B\",\"text\":\"tokoh utama\",\"isCorrect\":true,\"id\":\"ai-1781584071096-1-opt-1\"},{\"label\":\"C\",\"text\":\"tokoh antagonis saja\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-2\"},{\"label\":\"D\",\"text\":\"latar suasana\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-3\"},{\"label\":\"E\",\"text\":\"konflik eksternal\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006qsb8vwecdil3b','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-2\",\"tempId\":\"temp-1781584071096-2\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pernyataan berikut yang termasuk ciri kebahasaan teks dongeng adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menggunakan kalimat deskriptif untuk menggambarkan tokoh atau tempat\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-0\"},{\"label\":\"B\",\"text\":\"memakai dialog untuk menyampaikan jalan cerita secara dramatik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-1\"},{\"label\":\"C\",\"text\":\"mengandung data angka statistik sebagai bukti peristiwa\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-2\"},{\"label\":\"D\",\"text\":\"banyak menggunakan kata kerja tindakan (misalnya melangkah, berkata, berlari) untuk menggerakkan alur\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-3\"},{\"label\":\"E\",\"text\":\"mengutamakan fakta dan rujukan sumber seperti pada teks laporan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006rsb8vre8i29iy','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-3\",\"tempId\":\"temp-1781584071096-3\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis konflik (kiri) dengan contoh konflik dalam teks dongeng (kanan) yang sesuai.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Konflik batin\",\"response\":\"tokoh ragu antara menuruti hati dan takut pada akibat\",\"id\":\"ai-1781584071096-3-p0\"},{\"premise\":\"Konflik sosial\",\"response\":\"perbedaan kepentingan antarwarga membuat perselisihan\",\"id\":\"ai-1781584071096-3-p1\"},{\"premise\":\"Konflik alam\",\"response\":\"tokoh berhadapan dengan bencana atau kekuatan alam yang mengancam\",\"id\":\"ai-1781584071096-3-p2\"},{\"premise\":\"Konflik dengan tokoh lain\",\"response\":\"tokoh baik melawan tokoh jahat yang ingin mengambil sesuatu\",\"id\":\"ai-1781584071096-3-p3\"},{\"premise\":\"Konflik dengan diri sendiri (kelemahan karakter)\",\"response\":\"tokoh mengulang kesalahan karena sifat malas atau serakah\",\"id\":\"ai-1781584071096-3-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006ssb8vol682f49','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-4\",\"tempId\":\"temp-1781584071096-4\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat berikut yang paling tepat untuk menyatakan bagian struktur \'orientasi\' dalam teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Akhirnya, kutukan itu lenyap setelah ia menolong tanpa pamrih.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-0\"},{\"label\":\"B\",\"text\":\"Sejak pagi hari, desa itu bersiap menyambut bulan purnama yang ditunggu-tunggu.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-4-opt-1\"},{\"label\":\"C\",\"text\":\"Namun, rencana si serigala licik gagal total ketika mangsanya berpura-pura tidak takut.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-2\"},{\"label\":\"D\",\"text\":\"Begitulah ia memahami bahwa kebohongan selalu berujung pada penyesalan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-3\"},{\"label\":\"E\",\"text\":\"Pada malam itu, semua warga berduka karena kemarau panjang menghampiri ladang mereka.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006tsb8vinlm4rxd','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-5\",\"tempId\":\"temp-1781584071096-5\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Bacalah kalimat-kalimat dongeng berikut. Kalimat mana yang menunjukkan peristiwa sebab-akibat (kausalitas) secara jelas? (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Karena ia sering ingkar janji, raja akhirnya menjauhkan dirinya dari istana.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-0\"},{\"label\":\"B\",\"text\":\"Pada saat fajar menyingsing, burung-burung beterbangan di atas sungai.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-1\"},{\"label\":\"C\",\"text\":\"Akibat sifat serakah, harta yang ia kumpulkan berubah menjadi debu di genggamannya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-2\"},{\"label\":\"D\",\"text\":\"Ia berlari cepat, lalu tertawa bersama teman-temannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-3\"},{\"label\":\"E\",\"text\":\"Maka dari itu, ia belajar meminta maaf sebelum terlambat menyesal.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006usb8vfs77bpjc','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-6\",\"tempId\":\"temp-1781584071096-6\",\"type\":\"pilihan_ganda\",\"text\":\"Manakah pernyataan yang paling tepat tentang \'amanat\' dalam teks dongeng?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Amanat selalu dinyatakan secara eksplisit dalam satu kalimat langsung di akhir cerita.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat adalah tujuan penulis agar pembaca memahami karakter tokoh tanpa memberi pesan moral.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-1\"},{\"label\":\"C\",\"text\":\"Amanat merupakan pesan moral/pelajaran yang dapat ditarik dari peristiwa dan konflik dalam cerita.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-6-opt-2\"},{\"label\":\"D\",\"text\":\"Amanat hanya berupa deskripsi latar tempat yang membuat cerita lebih menarik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-3\"},{\"label\":\"E\",\"text\":\"Amanat identik dengan tema sehingga tidak perlu dianalisis secara terpisah.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006vsb8vuwrhhdog','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-7\",\"tempId\":\"temp-1781584071096-7\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis alur (kiri) dengan ciri peristiwanya (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Alur maju\",\"response\":\"peristiwa berjalan dari awal, tengah, menuju akhir secara kronologis\",\"id\":\"ai-1781584071096-7-p0\"},{\"premise\":\"Alur mundur\",\"response\":\"cerita diawali pada bagian akhir, lalu kembali menjelaskan peristiwa sebelumnya\",\"id\":\"ai-1781584071096-7-p1\"},{\"premise\":\"Alur campuran\",\"response\":\"menggabungkan alur maju dan mundur untuk membangun penjelasan konflik\",\"id\":\"ai-1781584071096-7-p2\"},{\"premise\":\"Alur dengan puncak konflik\",\"response\":\"mencapai titik paling menentukan yang membuat nasib tokoh berubah\",\"id\":\"ai-1781584071096-7-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006wsb8v1x1fez2g','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-8\",\"tempId\":\"temp-1781584071096-8\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pada teks dongeng, pilihan kata berikut yang biasanya mendukung nuansa cerita (naratif/khayal) adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"pada suatu hari\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-0\"},{\"label\":\"B\",\"text\":\"termasuk dalam laporan penelitian\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-1\"},{\"label\":\"C\",\"text\":\"tatkala angin berbisik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-2\"},{\"label\":\"D\",\"text\":\"berdasarkan data statistik tahun 2023\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-3\"},{\"label\":\"E\",\"text\":\"seketika itu juga\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wne006xsb8vt7ou8bof','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-9\",\"tempId\":\"temp-1781584071096-9\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat yang paling tepat untuk menyusun bagian \'penutup/hasil\' teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Setelah peristiwa itu, tokoh utama menyusun rencana baru untuk menantang bahaya berikutnya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-0\"},{\"label\":\"B\",\"text\":\"Ketika semuanya hening, si tokoh jahat menyadari kekeliruannya dan meminta maaf.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-9-opt-1\"},{\"label\":\"C\",\"text\":\"Di tengah jalan, angin semakin kencang dan ia terus berlari tanpa tujuan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-2\"},{\"label\":\"D\",\"text\":\"Pada suatu hari, hiduplah seorang anak yang rajin membantu orang tua.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-3\"},{\"label\":\"E\",\"text\":\"Karena ia sombong, banyak orang tidak mau bekerja sama dengannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wnf006ysb8v4ui677gf','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-10\",\"tempId\":\"temp-1781584071096-10\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan jenis tokoh (kiri) dengan perannya dalam konflik dongeng (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tokoh protagonis\",\"response\":\"membawa nilai baik dan umumnya menghadapi rintangan untuk mencapai tujuan\",\"id\":\"ai-1781584071096-10-p0\"},{\"premise\":\"Tokoh antagonis\",\"response\":\"menjadi penghambat yang menimbulkan konflik atau kerugian bagi tokoh lain\",\"id\":\"ai-1781584071096-10-p1\"},{\"premise\":\"Tokoh penolong\",\"response\":\"memberi bantuan, petunjuk, atau perlindungan dalam situasi sulit\",\"id\":\"ai-1781584071096-10-p2\"},{\"premise\":\"Tokoh yang menjadi korban\",\"response\":\"pihak yang dirugikan akibat tindakan tokoh antagonis atau keadaan\",\"id\":\"ai-1781584071096-10-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wnf006zsb8v5s6yhzhx','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-11\",\"tempId\":\"temp-1781584071096-11\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam analisis teks dongeng, manakah kegiatan yang paling tepat untuk menentukan \'tema\'?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menghafalkan nama tokoh satu per satu agar cerita mudah diingat\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-0\"},{\"label\":\"B\",\"text\":\"mencari gagasan utama yang berulang lewat peristiwa dan konflik dalam cerita\",\"isCorrect\":true,\"id\":\"ai-1781584071096-11-opt-1\"},{\"label\":\"C\",\"text\":\"menentukan apakah latar terjadi di desa atau kota sebagai tema utama\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-2\"},{\"label\":\"D\",\"text\":\"mengukur panjang kalimat agar sesuai kaidah penulisan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-3\"},{\"label\":\"E\",\"text\":\"menentukan jenis huruf yang digunakan dalam teks\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wnf0070sb8vok1pfs1n','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-12\",\"tempId\":\"temp-1781584071096-12\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Identifikasi bagian yang menunjukkan \'kemunculan konflik\' dalam dongeng. Pilih semua pernyataan yang benar. (diasumsikan konflik mulai saat masalah pokok pertama kali dipersengketakan).\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Tokoh utama mengetahui bahwa janji yang ia buat tidak dapat ditepati karena sesuatu yang di luar kendalinya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-0\"},{\"label\":\"B\",\"text\":\"Tokoh jahat menyembunyikan benda penting sehingga tokoh utama kehilangan jalan untuk menyelesaikan masalah.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-1\"},{\"label\":\"C\",\"text\":\"Tokoh utama berkelana mencari petunjuk setelah mendapatkan informasi awal tentang keberadaan benda itu.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-2\"},{\"label\":\"D\",\"text\":\"Tindakan tokoh antagonis menimbulkan pertentangan terbuka yang memicu serangkaian peristiwa berikutnya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-3\"},{\"label\":\"E\",\"text\":\"Kemudian tokoh utama menemukan solusi dan konflik selesai dengan kemenangan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wnf0071sb8vw2c1c3tw','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-13\",\"tempId\":\"temp-1781584071096-13\",\"type\":\"pilihan_ganda\",\"text\":\"Perhatikan dua kalimat berikut yang berasal dari dongeng: (1) \'Akhirnya ia mengaku dan meminta maaf.\' (2) \'Ia mengaku dan meminta maaf, lalu semua warga menerimanya kembali.\' Kalimat mana yang lebih tepat untuk menggambarkan hubungan urutan peristiwa dalam alur?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Kalimat (1) karena ada kata \'akhirnya\'.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-0\"},{\"label\":\"B\",\"text\":\"Kalimat (2) karena menampilkan urutan dengan \'lalu\'.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-13-opt-1\"},{\"label\":\"C\",\"text\":\"Keduanya sama karena keduanya hanya berisi pengakuan tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-2\"},{\"label\":\"D\",\"text\":\"Kalimat (1) karena \'akhirnya\' adalah penanda konflik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-3\"},{\"label\":\"E\",\"text\":\"Kalimat (2) salah karena menggunakan \'lalu\' sehingga tidak termasuk teks dongeng.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wnf0072sb8vkyww2ozy','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-14\",\"tempId\":\"temp-1781584071096-14\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pilih pernyataan yang tepat tentang hubungan tema, konflik, dan amanat dalam teks dongeng. (pilih semua yang benar)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Konflik menjadi sarana untuk menguji nilai-nilai yang terkait dengan tema.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat selalu identik dengan solusi konflik tanpa mempertimbangkan peristiwa lain.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-1\"},{\"label\":\"C\",\"text\":\"Tema dapat ditarik dari pola peristiwa, sedangkan amanat merupakan pelajaran moral yang dapat disimpulkan dari hasil akhir.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-2\"},{\"label\":\"D\",\"text\":\"Konflik tidak diperlukan dalam dongeng karena dongeng hanya berisi deskripsi tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-3\"},{\"label\":\"E\",\"text\":\"Jika tokoh protagonis menerima konsekuensi karena tindakan tertentu, amanat umumnya dapat ditafsirkan melalui konsekuensi tersebut.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.339','2026-06-16 04:28:03.339'),
('cmqg55wua0073sb8v0c6k5bm3','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-0\",\"tempId\":\"temp-1781584071096-0\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan unsur intrinsik teks dongeng (kiri) dengan definisinya (kanan) secara tepat.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tema\",\"response\":\"gagasan utama yang mendasari jalan cerita\",\"id\":\"ai-1781584071096-0-p0\"},{\"premise\":\"Alur\",\"response\":\"rangkaian peristiwa dari awal hingga akhir\",\"id\":\"ai-1781584071096-0-p1\"},{\"premise\":\"Tokoh\",\"response\":\"pelaku dalam cerita yang menjalankan peristiwa\",\"id\":\"ai-1781584071096-0-p2\"},{\"premise\":\"Latar\",\"response\":\"tempat, waktu, dan suasana terjadinya peristiwa\",\"id\":\"ai-1781584071096-0-p3\"},{\"premise\":\"Amanat\",\"response\":\"pesan moral atau pelajaran yang ingin disampaikan\",\"id\":\"ai-1781584071096-0-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua0074sb8vky726equ','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-1\",\"tempId\":\"temp-1781584071096-1\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam teks dongeng, tokoh yang digambarkan memiliki sifat dominan dan menjadi penggerak utama peristiwa disebut ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"tokoh figuran\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-0\"},{\"label\":\"B\",\"text\":\"tokoh utama\",\"isCorrect\":true,\"id\":\"ai-1781584071096-1-opt-1\"},{\"label\":\"C\",\"text\":\"tokoh antagonis saja\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-2\"},{\"label\":\"D\",\"text\":\"latar suasana\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-3\"},{\"label\":\"E\",\"text\":\"konflik eksternal\",\"isCorrect\":false,\"id\":\"ai-1781584071096-1-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua0075sb8v2kur7h7f','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-2\",\"tempId\":\"temp-1781584071096-2\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pernyataan berikut yang termasuk ciri kebahasaan teks dongeng adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menggunakan kalimat deskriptif untuk menggambarkan tokoh atau tempat\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-0\"},{\"label\":\"B\",\"text\":\"memakai dialog untuk menyampaikan jalan cerita secara dramatik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-1\"},{\"label\":\"C\",\"text\":\"mengandung data angka statistik sebagai bukti peristiwa\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-2\"},{\"label\":\"D\",\"text\":\"banyak menggunakan kata kerja tindakan (misalnya melangkah, berkata, berlari) untuk menggerakkan alur\",\"isCorrect\":true,\"id\":\"ai-1781584071096-2-opt-3\"},{\"label\":\"E\",\"text\":\"mengutamakan fakta dan rujukan sumber seperti pada teks laporan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-2-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua0076sb8vaqjqdhbw','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-3\",\"tempId\":\"temp-1781584071096-3\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis konflik (kiri) dengan contoh konflik dalam teks dongeng (kanan) yang sesuai.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Konflik batin\",\"response\":\"tokoh ragu antara menuruti hati dan takut pada akibat\",\"id\":\"ai-1781584071096-3-p0\"},{\"premise\":\"Konflik sosial\",\"response\":\"perbedaan kepentingan antarwarga membuat perselisihan\",\"id\":\"ai-1781584071096-3-p1\"},{\"premise\":\"Konflik alam\",\"response\":\"tokoh berhadapan dengan bencana atau kekuatan alam yang mengancam\",\"id\":\"ai-1781584071096-3-p2\"},{\"premise\":\"Konflik dengan tokoh lain\",\"response\":\"tokoh baik melawan tokoh jahat yang ingin mengambil sesuatu\",\"id\":\"ai-1781584071096-3-p3\"},{\"premise\":\"Konflik dengan diri sendiri (kelemahan karakter)\",\"response\":\"tokoh mengulang kesalahan karena sifat malas atau serakah\",\"id\":\"ai-1781584071096-3-p4\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua0077sb8vdpkiy2c0','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-4\",\"tempId\":\"temp-1781584071096-4\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat berikut yang paling tepat untuk menyatakan bagian struktur \'orientasi\' dalam teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Akhirnya, kutukan itu lenyap setelah ia menolong tanpa pamrih.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-0\"},{\"label\":\"B\",\"text\":\"Sejak pagi hari, desa itu bersiap menyambut bulan purnama yang ditunggu-tunggu.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-4-opt-1\"},{\"label\":\"C\",\"text\":\"Namun, rencana si serigala licik gagal total ketika mangsanya berpura-pura tidak takut.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-2\"},{\"label\":\"D\",\"text\":\"Begitulah ia memahami bahwa kebohongan selalu berujung pada penyesalan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-3\"},{\"label\":\"E\",\"text\":\"Pada malam itu, semua warga berduka karena kemarau panjang menghampiri ladang mereka.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-4-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua0078sb8vfnba885f','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-5\",\"tempId\":\"temp-1781584071096-5\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Bacalah kalimat-kalimat dongeng berikut. Kalimat mana yang menunjukkan peristiwa sebab-akibat (kausalitas) secara jelas? (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Karena ia sering ingkar janji, raja akhirnya menjauhkan dirinya dari istana.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-0\"},{\"label\":\"B\",\"text\":\"Pada saat fajar menyingsing, burung-burung beterbangan di atas sungai.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-1\"},{\"label\":\"C\",\"text\":\"Akibat sifat serakah, harta yang ia kumpulkan berubah menjadi debu di genggamannya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-2\"},{\"label\":\"D\",\"text\":\"Ia berlari cepat, lalu tertawa bersama teman-temannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-5-opt-3\"},{\"label\":\"E\",\"text\":\"Maka dari itu, ia belajar meminta maaf sebelum terlambat menyesal.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-5-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua0079sb8vsjf169r2','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-6\",\"tempId\":\"temp-1781584071096-6\",\"type\":\"pilihan_ganda\",\"text\":\"Manakah pernyataan yang paling tepat tentang \'amanat\' dalam teks dongeng?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Amanat selalu dinyatakan secara eksplisit dalam satu kalimat langsung di akhir cerita.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat adalah tujuan penulis agar pembaca memahami karakter tokoh tanpa memberi pesan moral.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-1\"},{\"label\":\"C\",\"text\":\"Amanat merupakan pesan moral/pelajaran yang dapat ditarik dari peristiwa dan konflik dalam cerita.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-6-opt-2\"},{\"label\":\"D\",\"text\":\"Amanat hanya berupa deskripsi latar tempat yang membuat cerita lebih menarik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-3\"},{\"label\":\"E\",\"text\":\"Amanat identik dengan tema sehingga tidak perlu dianalisis secara terpisah.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-6-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007asb8vsn4fqnpp','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-7\",\"tempId\":\"temp-1781584071096-7\",\"type\":\"menjodohkan\",\"text\":\"Pasangkan jenis alur (kiri) dengan ciri peristiwanya (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Alur maju\",\"response\":\"peristiwa berjalan dari awal, tengah, menuju akhir secara kronologis\",\"id\":\"ai-1781584071096-7-p0\"},{\"premise\":\"Alur mundur\",\"response\":\"cerita diawali pada bagian akhir, lalu kembali menjelaskan peristiwa sebelumnya\",\"id\":\"ai-1781584071096-7-p1\"},{\"premise\":\"Alur campuran\",\"response\":\"menggabungkan alur maju dan mundur untuk membangun penjelasan konflik\",\"id\":\"ai-1781584071096-7-p2\"},{\"premise\":\"Alur dengan puncak konflik\",\"response\":\"mencapai titik paling menentukan yang membuat nasib tokoh berubah\",\"id\":\"ai-1781584071096-7-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007bsb8vnmjxy9vb','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-8\",\"tempId\":\"temp-1781584071096-8\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pada teks dongeng, pilihan kata berikut yang biasanya mendukung nuansa cerita (naratif/khayal) adalah .... (pilih semua yang tepat)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"pada suatu hari\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-0\"},{\"label\":\"B\",\"text\":\"termasuk dalam laporan penelitian\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-1\"},{\"label\":\"C\",\"text\":\"tatkala angin berbisik\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-2\"},{\"label\":\"D\",\"text\":\"berdasarkan data statistik tahun 2023\",\"isCorrect\":false,\"id\":\"ai-1781584071096-8-opt-3\"},{\"label\":\"E\",\"text\":\"seketika itu juga\",\"isCorrect\":true,\"id\":\"ai-1781584071096-8-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007csb8v2mmjxjdr','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-9\",\"tempId\":\"temp-1781584071096-9\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat yang paling tepat untuk menyusun bagian \'penutup/hasil\' teks dongeng adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Setelah peristiwa itu, tokoh utama menyusun rencana baru untuk menantang bahaya berikutnya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-0\"},{\"label\":\"B\",\"text\":\"Ketika semuanya hening, si tokoh jahat menyadari kekeliruannya dan meminta maaf.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-9-opt-1\"},{\"label\":\"C\",\"text\":\"Di tengah jalan, angin semakin kencang dan ia terus berlari tanpa tujuan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-2\"},{\"label\":\"D\",\"text\":\"Pada suatu hari, hiduplah seorang anak yang rajin membantu orang tua.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-3\"},{\"label\":\"E\",\"text\":\"Karena ia sombong, banyak orang tidak mau bekerja sama dengannya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-9-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007dsb8v82887f6o','Bahasa Indonesia','Kelas X','teks dongeng','sulit','menjodohkan','{\"id\":\"ai-1781584071096-10\",\"tempId\":\"temp-1781584071096-10\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan jenis tokoh (kiri) dengan perannya dalam konflik dongeng (kanan).\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Tokoh protagonis\",\"response\":\"membawa nilai baik dan umumnya menghadapi rintangan untuk mencapai tujuan\",\"id\":\"ai-1781584071096-10-p0\"},{\"premise\":\"Tokoh antagonis\",\"response\":\"menjadi penghambat yang menimbulkan konflik atau kerugian bagi tokoh lain\",\"id\":\"ai-1781584071096-10-p1\"},{\"premise\":\"Tokoh penolong\",\"response\":\"memberi bantuan, petunjuk, atau perlindungan dalam situasi sulit\",\"id\":\"ai-1781584071096-10-p2\"},{\"premise\":\"Tokoh yang menjadi korban\",\"response\":\"pihak yang dirugikan akibat tindakan tokoh antagonis atau keadaan\",\"id\":\"ai-1781584071096-10-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007esb8vb6m1kas2','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-11\",\"tempId\":\"temp-1781584071096-11\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam analisis teks dongeng, manakah kegiatan yang paling tepat untuk menentukan \'tema\'?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"menghafalkan nama tokoh satu per satu agar cerita mudah diingat\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-0\"},{\"label\":\"B\",\"text\":\"mencari gagasan utama yang berulang lewat peristiwa dan konflik dalam cerita\",\"isCorrect\":true,\"id\":\"ai-1781584071096-11-opt-1\"},{\"label\":\"C\",\"text\":\"menentukan apakah latar terjadi di desa atau kota sebagai tema utama\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-2\"},{\"label\":\"D\",\"text\":\"mengukur panjang kalimat agar sesuai kaidah penulisan\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-3\"},{\"label\":\"E\",\"text\":\"menentukan jenis huruf yang digunakan dalam teks\",\"isCorrect\":false,\"id\":\"ai-1781584071096-11-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007fsb8vggdjov0o','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-12\",\"tempId\":\"temp-1781584071096-12\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Identifikasi bagian yang menunjukkan \'kemunculan konflik\' dalam dongeng. Pilih semua pernyataan yang benar. (diasumsikan konflik mulai saat masalah pokok pertama kali dipersengketakan).\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Tokoh utama mengetahui bahwa janji yang ia buat tidak dapat ditepati karena sesuatu yang di luar kendalinya.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-0\"},{\"label\":\"B\",\"text\":\"Tokoh jahat menyembunyikan benda penting sehingga tokoh utama kehilangan jalan untuk menyelesaikan masalah.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-1\"},{\"label\":\"C\",\"text\":\"Tokoh utama berkelana mencari petunjuk setelah mendapatkan informasi awal tentang keberadaan benda itu.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-2\"},{\"label\":\"D\",\"text\":\"Tindakan tokoh antagonis menimbulkan pertentangan terbuka yang memicu serangkaian peristiwa berikutnya.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-12-opt-3\"},{\"label\":\"E\",\"text\":\"Kemudian tokoh utama menemukan solusi dan konflik selesai dengan kemenangan.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-12-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007gsb8v9bg9tdlg','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda','{\"id\":\"ai-1781584071096-13\",\"tempId\":\"temp-1781584071096-13\",\"type\":\"pilihan_ganda\",\"text\":\"Perhatikan dua kalimat berikut yang berasal dari dongeng: (1) \'Akhirnya ia mengaku dan meminta maaf.\' (2) \'Ia mengaku dan meminta maaf, lalu semua warga menerimanya kembali.\' Kalimat mana yang lebih tepat untuk menggambarkan hubungan urutan peristiwa dalam alur?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Kalimat (1) karena ada kata \'akhirnya\'.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-0\"},{\"label\":\"B\",\"text\":\"Kalimat (2) karena menampilkan urutan dengan \'lalu\'.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-13-opt-1\"},{\"label\":\"C\",\"text\":\"Keduanya sama karena keduanya hanya berisi pengakuan tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-2\"},{\"label\":\"D\",\"text\":\"Kalimat (1) karena \'akhirnya\' adalah penanda konflik.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-3\"},{\"label\":\"E\",\"text\":\"Kalimat (2) salah karena menggunakan \'lalu\' sehingga tidak termasuk teks dongeng.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-13-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg55wua007hsb8vrct512wg','Bahasa Indonesia','Kelas X','teks dongeng','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781584071096-14\",\"tempId\":\"temp-1781584071096-14\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Pilih pernyataan yang tepat tentang hubungan tema, konflik, dan amanat dalam teks dongeng. (pilih semua yang benar)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Konflik menjadi sarana untuk menguji nilai-nilai yang terkait dengan tema.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-0\"},{\"label\":\"B\",\"text\":\"Amanat selalu identik dengan solusi konflik tanpa mempertimbangkan peristiwa lain.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-1\"},{\"label\":\"C\",\"text\":\"Tema dapat ditarik dari pola peristiwa, sedangkan amanat merupakan pelajaran moral yang dapat disimpulkan dari hasil akhir.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-2\"},{\"label\":\"D\",\"text\":\"Konflik tidak diperlukan dalam dongeng karena dongeng hanya berisi deskripsi tokoh.\",\"isCorrect\":false,\"id\":\"ai-1781584071096-14-opt-3\"},{\"label\":\"E\",\"text\":\"Jika tokoh protagonis menerima konsekuensi karena tindakan tertentu, amanat umumnya dapat ditafsirkan melalui konsekuensi tersebut.\",\"isCorrect\":true,\"id\":\"ai-1781584071096-14-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:28:03.586','2026-06-16 04:28:03.586'),
('cmqg66f4k007isb8v2zu959y8','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','menjodohkan','{\"id\":\"ai-1781585762400-0\",\"tempId\":\"temp-1781585762400-0\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan jenis kalimat pada kolom kiri dengan fungsi komunikatifnya pada kolom kanan.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Kalimat imperatif persuasif\",\"response\":\"Memberi ajakan dengan nada yang mengharapkan tindakan\",\"id\":\"ai-1781585762400-0-p0\"},{\"premise\":\"Kalimat interogatif retoris\",\"response\":\"Tidak menunggu jawaban; lebih menguatkan penegasan\",\"id\":\"ai-1781585762400-0-p1\"},{\"premise\":\"Kalimat deklaratif\",\"response\":\"Menyatakan informasi atau pendapat\",\"id\":\"ai-1781585762400-0-p2\"},{\"premise\":\"Kalimat seruan\",\"response\":\"Mengungkapkan perasaan kuat atau respons spontan\",\"id\":\"ai-1781585762400-0-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007jsb8v9v74187y','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','menjodohkan','{\"id\":\"ai-1781585762400-1\",\"tempId\":\"temp-1781585762400-1\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan istilah kebahasaan pada kolom kiri dengan penjelasan yang tepat pada kolom kanan.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Koherensi\",\"response\":\"Keterkaitan makna antarbagian teks sehingga alurnya terasa utuh\",\"id\":\"ai-1781585762400-1-p0\"},{\"premise\":\"Kohesi\",\"response\":\"Keterikatan bentuk antarunsur teks melalui perangkat kebahasaan\",\"id\":\"ai-1781585762400-1-p1\"},{\"premise\":\"Elipsis\",\"response\":\"Penghilangan unsur tertentu yang dapat dipahami dari konteks\",\"id\":\"ai-1781585762400-1-p2\"},{\"premise\":\"Anafora\",\"response\":\"Pengacuan kata ke anteseden yang disebut lebih dahulu\",\"id\":\"ai-1781585762400-1-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007ksb8v0ft9lrhl','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','menjodohkan','{\"id\":\"ai-1781585762400-2\",\"tempId\":\"temp-1781585762400-2\",\"type\":\"menjodohkan\",\"text\":\"Jodohkan ragam bahasa pada kolom kiri dengan ciri kebahasaan yang sesuai pada kolom kanan.\",\"difficulty\":\"sulit\",\"matchingPairs\":[{\"premise\":\"Ragam resmi\",\"response\":\"Menggunakan pilihan kata baku dan kalimat efektif\",\"id\":\"ai-1781585762400-2-p0\"},{\"premise\":\"Ragam tidak resmi\",\"response\":\"Lebih lentur, sering memakai kata sehari-hari dan variasi ekspresi\",\"id\":\"ai-1781585762400-2-p1\"},{\"premise\":\"Ragam ilmiah\",\"response\":\"Cenderung objektif, memakai istilah teknis, serta kalimat yang logis\",\"id\":\"ai-1781585762400-2-p2\"},{\"premise\":\"Ragam sastra\",\"response\":\"Mengutamakan nilai estetika melalui gaya bahasa dan imaji\",\"id\":\"ai-1781585762400-2-p3\"}],\"points\":20,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007lsb8vv5wahs8t','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda','{\"id\":\"ai-1781585762400-3\",\"tempId\":\"temp-1781585762400-3\",\"type\":\"pilihan_ganda\",\"text\":\"Perhatikan kutipan teks berikut: \\\"Meskipun jadwal proyek telah berubah, tim tetap menyelesaikan pekerjaan sesuai target.\\\" Kalimat tersebut termasuk jenis hubungan antarbagian yang paling tepat adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Sebab-akibat karena satu peristiwa menjadi akibat dari peristiwa lain\",\"isCorrect\":false,\"id\":\"ai-1781585762400-3-opt-0\"},{\"label\":\"B\",\"text\":\"Pertentangan karena ada unsur kendala tetapi diikuti kepatuhan terhadap target\",\"isCorrect\":true,\"id\":\"ai-1781585762400-3-opt-1\"},{\"label\":\"C\",\"text\":\"Tambahan karena satu gagasan menambah gagasan lain tanpa konflik\",\"isCorrect\":false,\"id\":\"ai-1781585762400-3-opt-2\"},{\"label\":\"D\",\"text\":\"Tujuan karena kalimat berorientasi pada maksud tindakan\",\"isCorrect\":false,\"id\":\"ai-1781585762400-3-opt-3\"},{\"label\":\"E\",\"text\":\"Akibat-sebab karena target menjadi sebab perubahan jadwal\",\"isCorrect\":false,\"id\":\"ai-1781585762400-3-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007msb8vvl36c6xc','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda','{\"id\":\"ai-1781585762400-4\",\"tempId\":\"temp-1781585762400-4\",\"type\":\"pilihan_ganda\",\"text\":\"Manakah kalimat yang paling memenuhi kaidah penggunaan kata baku dan ejaan (tata tulis) untuk konteks laporan hasil pengamatan?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Hasil pengamatan memperlihatkan bahwa tanaman itu tumbuh dengan baik.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-4-opt-0\"},{\"label\":\"B\",\"text\":\"Hasil pengamatan menunjukkan bahwasanya tanaman itu berkembang secara baik.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-4-opt-1\"},{\"label\":\"C\",\"text\":\"Dari pengamatan, tanaman tersebut kelihatan tumbuh dengan bagus.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-4-opt-2\"},{\"label\":\"D\",\"text\":\"Pengamatan memperlihatkan kalau tanaman itu tumbuh dengan baik sekali.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-4-opt-3\"},{\"label\":\"E\",\"text\":\"Pengamatan di lapangan membuktikan bahwa tanaman itu tumbuh dengan baiknya.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-4-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007nsb8vjt23eesz','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda','{\"id\":\"ai-1781585762400-5\",\"tempId\":\"temp-1781585762400-5\",\"type\":\"pilihan_ganda\",\"text\":\"Dalam kalimat: \\\"Dokumen itu telah saya simpan sejak minggu lalu.\\\" Perbaikan yang paling tepat jika ingin menonjolkan fokus pada dokumen adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"\\\"Dokumen itu telah saya simpan sejak minggu lalu oleh saya.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-5-opt-0\"},{\"label\":\"B\",\"text\":\"\\\"Dokumen itu telah saya simpan sejak minggu lalu.\\\" (tetap, sudah fokus pada objek)\",\"isCorrect\":true,\"id\":\"ai-1781585762400-5-opt-1\"},{\"label\":\"C\",\"text\":\"\\\"Saya simpan dokumen itu sejak minggu lalu.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-5-opt-2\"},{\"label\":\"D\",\"text\":\"\\\"Dokumen itu sejak minggu lalu telah tersimpan oleh saya.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-5-opt-3\"},{\"label\":\"E\",\"text\":\"\\\"Sejak minggu lalu, dokumen itu telah saya simpan.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-5-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007osb8vdvo1p983','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda','{\"id\":\"ai-1781585762400-6\",\"tempId\":\"temp-1781585762400-6\",\"type\":\"pilihan_ganda\",\"text\":\"Baca kalimat berikut: \\\"Bukan hanya siswa yang aktif, tetapi juga gurunya ikut membimbing.\\\" Pilihan yang menunjukkan pola hubungan yang benar adalah ....\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Penegasan positif satu pihak tanpa perbandingan\",\"isCorrect\":false,\"id\":\"ai-1781585762400-6-opt-0\"},{\"label\":\"B\",\"text\":\"Pertentangan dua pihak dengan kata penghubung kontras\",\"isCorrect\":false,\"id\":\"ai-1781585762400-6-opt-1\"},{\"label\":\"C\",\"text\":\"Korelasi/penegasan ganda: tidak hanya A, tetapi juga B\",\"isCorrect\":true,\"id\":\"ai-1781585762400-6-opt-2\"},{\"label\":\"D\",\"text\":\"Sebab-akibat yang menunjukkan alasan dan hasil\",\"isCorrect\":false,\"id\":\"ai-1781585762400-6-opt-3\"},{\"label\":\"E\",\"text\":\"Perbandingan satu pihak saja menggunakan komparatif\",\"isCorrect\":false,\"id\":\"ai-1781585762400-6-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007psb8vbg2roh49','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda','{\"id\":\"ai-1781585762400-7\",\"tempId\":\"temp-1781585762400-7\",\"type\":\"pilihan_ganda\",\"text\":\"Kalimat mana yang paling tepat menggunakan ejaan dan tanda baca saat memuat kutipan langsung?\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Menurut penulis, \\\"ketelitian adalah kunci\\\" sehingga kita harus teliti.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-7-opt-0\"},{\"label\":\"B\",\"text\":\"Menurut penulis, \\\"ketelitian adalah kunci\\\"; sehingga kita harus teliti.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-7-opt-1\"},{\"label\":\"C\",\"text\":\"Menurut penulis \\\"ketelitian adalah kunci\\\" sehingga kita harus teliti.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-7-opt-2\"},{\"label\":\"D\",\"text\":\"Menurut penulis: \\\"ketelitian adalah kunci\\\" sehingga kita harus teliti.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-7-opt-3\"},{\"label\":\"E\",\"text\":\"Menurut penulis, \\\"ketelitian adalah kunci\\\" sehingga, kita harus teliti.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-7-opt-4\"}],\"points\":10,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007qsb8vi66qnh0k','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781585762400-8\",\"tempId\":\"temp-1781585762400-8\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Perhatikan bagian teks berikut: \\\"Dalam pembahasan tersebut, penulis menegaskan bahwa fenomena sosial tidak dapat dipahami secara parsial. Oleh karena itu, pembaca perlu melihat konteks sejarahnya.\\\" Pernyataan mana yang benar mengenai aspek kebahasaan teks tersebut? (Pilih semua yang tepat.)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Ada penanda hubungan sebab-akibat yang ditunjukkan oleh kata penghubung \'Oleh karena itu\'.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-8-opt-0\"},{\"label\":\"B\",\"text\":\"Kata \'parsial\' termasuk istilah umum dan seharusnya diganti menjadi kata \'sebagian\' agar lebih baku.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-8-opt-1\"},{\"label\":\"C\",\"text\":\"Frasa \'konteks sejarahnya\' berfungsi sebagai bagian yang melengkapi gagasan agar makna tidak kabur.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-8-opt-2\"},{\"label\":\"D\",\"text\":\"Kalimat kedua bersifat tambahan saja tanpa pengaruh terhadap interpretasi kalimat pertama.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-8-opt-3\"},{\"label\":\"E\",\"text\":\"Teks menggunakan gaya bahasa ilmiah dengan pilihan kata yang cenderung objektif dan bernuansa logis.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-8-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007rsb8vlmgjei2l','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781585762400-9\",\"tempId\":\"temp-1781585762400-9\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Manakah tindakan revisi yang secara kebahasaan tepat untuk memperbaiki paragraf berikut agar lebih efektif? Paragraf: \\\"Bagi mahasiswa yang belum menyerahkan tugas, dimohon untuk segera menyerahkan. Hal ini supaya tidak tertunda.\\\" (Pilih semua yang tepat.)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Menghilangkan pengulangan dengan mengubah menjadi satu imperatif yang padu, misalnya: \\\"Mahasiswa yang belum menyerahkan tugas, mohon segera menyerahkan.\\\"\",\"isCorrect\":true,\"id\":\"ai-1781585762400-9-opt-0\"},{\"label\":\"B\",\"text\":\"Mengganti \\\"dimohon untuk\\\" dengan \\\"diimbau agar\\\" agar lebih efektif namun tetap sesuai ragam resmi.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-9-opt-1\"},{\"label\":\"C\",\"text\":\"Tetap mempertahankan kalimat terakhir, tetapi ubah menjadi: \\\"Supaya tidak tertunda.\\\" agar lebih ringkas.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-9-opt-2\"},{\"label\":\"D\",\"text\":\"Menambah kata \\\"segera\\\" dua kali agar penekanan makin kuat.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-9-opt-3\"},{\"label\":\"E\",\"text\":\"Mengubah \\\"Hal ini\\\" menjadi \\\"Tugas\\\" supaya rujukan lebih jelas: \\\"Tugas ini agar tidak tertunda.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-9-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007ssb8vrd28mpm9','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781585762400-10\",\"tempId\":\"temp-1781585762400-10\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Baca kalimat-kalimat berikut. Pilih kalimat yang memperlihatkan penggunaan kata hubung korelatif (bukan sekadar konjungsi biasa) yang tepat. (Pilih semua yang benar.)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"\\\"Baik siswa maupun guru ikut berpartisipasi dalam kegiatan tersebut.\\\"\",\"isCorrect\":true,\"id\":\"ai-1781585762400-10-opt-0\"},{\"label\":\"B\",\"text\":\"\\\"Tidak hanya mahasiswa yang datang, tetapi juga dosennya ikut hadir.\\\"\",\"isCorrect\":true,\"id\":\"ai-1781585762400-10-opt-1\"},{\"label\":\"C\",\"text\":\"\\\"Entah dia yang salah atau kita yang kurang memahami.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-10-opt-2\"},{\"label\":\"D\",\"text\":\"\\\"Semakin kamu belajar, maka semakin kamu memahami materi.\\\"\",\"isCorrect\":false,\"id\":\"ai-1781585762400-10-opt-3\"},{\"label\":\"E\",\"text\":\"\\\"Aku bukan berarti tidak setuju, melainkan ingin dibahas lebih lanjut.\\\"\",\"isCorrect\":true,\"id\":\"ai-1781585762400-10-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899'),
('cmqg66f4k007tsb8v9ox4hciy','Bahasa Indonesia','Kelas X','Bahasa Indonesia','sulit','pilihan_ganda_kompleks','{\"id\":\"ai-1781585762400-11\",\"tempId\":\"temp-1781585762400-11\",\"type\":\"pilihan_ganda_kompleks\",\"text\":\"Sebuah teks eksposisi dinilai memiliki struktur yang tepat. Manakah pernyataan berikut yang sesuai dengan ciri bagian tesis, argumen, dan penegasan ulang? (Pilih semua yang tepat.)\",\"difficulty\":\"sulit\",\"options\":[{\"label\":\"A\",\"text\":\"Tesis memuat pendapat awal penulis tentang topik yang akan dibahas.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-11-opt-0\"},{\"label\":\"B\",\"text\":\"Argumen sebaiknya berisi data, fakta, atau penalaran untuk mendukung tesis.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-11-opt-1\"},{\"label\":\"C\",\"text\":\"Penegasan ulang hanya mengulang kalimat tesis tanpa menambah sisi pertimbangan apa pun.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-11-opt-2\"},{\"label\":\"D\",\"text\":\"Penegasan ulang dapat menyimpulkan kembali gagasan agar pembaca memahami posisi penulis.\",\"isCorrect\":true,\"id\":\"ai-1781585762400-11-opt-3\"},{\"label\":\"E\",\"text\":\"Argumen boleh berbentuk opini tanpa alasan asalkan ditulis dengan kata-kata persuasif.\",\"isCorrect\":false,\"id\":\"ai-1781585762400-11-opt-4\"}],\"points\":15,\"isSelected\":true}','2026-06-16 04:56:26.899','2026-06-16 04:56:26.899');
